(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-175":{scenario:{company:"Pinehill Bank",supervisor:{name:"Phan Thị Ngọc Mai",role:{vi:"Kiểm soát viên Giao dịch",en:"Teller Supervisor"}},ref_code:"STK-3305",title:{vi:"Đúng lãi suất. Đúng tiền. Đúng khách hàng.",en:"Right rate. Right amount. Right customer."},brief:{vi:"Khách hàng 72 tuổi đến tất toán trước hạn sổ tiết kiệm STK-3305: gốc 365000000 đồng, kỳ hạn 6 tháng, lãi suất 5,6%/năm, đã gửi 120 ngày. Biểu lãi suất của ngân hàng: rút trước hạn hưởng lãi suất không kỳ hạn 0,2%/năm (số liệu mô phỏng), tính theo số ngày thực tế/365. Phiếu chi nháp áp lãi suất kỳ hạn. Hãy sửa lãi suất áp dụng và tiền lãi, giải thích rõ cho khách, rồi lập báo cáo.",en:"A 72-year-old customer wants to close savings book STK-3305 early: principal 365000000 VND, 6-month term at 5.6% per year, held for 120 days. The bank's rate sheet: early withdrawal earns the demand deposit rate of 0.2% per year (training data), actual days/365. The draft payout slip applies the term rate. Correct the applied rate and the interest, explain it clearly to the customer, then report."},reference_title:{vi:"Biểu lãi suất & phiếu tính lãi đã duyệt · STK-3305",en:"Approved rate sheet & interest slip · STK-3305"},fields:[{id:"RATE_APPLIED",label:{vi:"Lãi suất áp dụng (%/năm)",en:"Applied rate (% per year)"},initial:"5.6%",expected:"0.2%",choices:["5.6%","2.9%","0.2%"],reference:"Biểu lãi suất tiền gửi hiện hành",ref_value:{vi:"Đúng hạn 6 tháng: 5,6%; kỳ hạn 3 tháng: 2,9%; rút trước hạn: lãi suất không kỳ hạn 0,2%",en:"6-month at maturity: 5.6%; 3-month term: 2.9%; early withdrawal: demand rate 0.2%"},hint:{vi:"Rút trước hạn không được hưởng lãi suất kỳ hạn đã cam kết, kể cả kỳ hạn ngắn hơn đã trôi qua.",en:"An early withdrawal earns neither the committed term rate nor a shorter term already elapsed."}},{id:"INTEREST_VND",label:{vi:"Tiền lãi trả khách (đồng)",en:"Interest paid (VND)"},initial:"6720000",expected:"240000",reference:"Phiếu tính lãi rút trước hạn",ref_value:{vi:"Gốc 365000000 đồng; đã gửi 120 ngày; cơ sở tính 365 ngày",en:"Principal 365000000 VND; 120 days held; 365-day basis"},hint:{vi:"Nhân gốc với lãi suất năm đúng, rồi nhân số ngày thực gửi và chia 365.",en:"Multiply the principal by the correct annual rate, then by actual days and divide by 365."}}],sop32:{vi:"Tiền lãi = số tiền gốc x lãi suất áp dụng (%/năm) x số ngày gửi thực tế / 365; rút trước hạn áp dụng lãi suất không kỳ hạn theo biểu lãi suất tại ngày rút.",en:"Interest = principal x applied annual rate x actual days held / 365; early withdrawal uses the demand deposit rate on the sheet at the withdrawal date."},context:{label:"CORE BANKING / STK-3305",metrics:[{label:{vi:"Số tiền gốc",en:"Principal"},value:"365,000,000 VND"},{label:{vi:"Số ngày đã gửi",en:"Days held"},value:"120"},{label:{vi:"Lãi suất kỳ hạn",en:"Term rate"},value:"5.6%"}]},crisis:{vi:"Khách vừa nghe điện thoại vừa giục: “Bên công an bảo phải chuyển ngay toàn bộ tiền vào tài khoản tạm giữ này để phục vụ điều tra, cấm nói với ai.” Hàng chờ phía sau phàn nàn và đề nghị bạn làm nhanh cho xong.",en:"The customer, still on the phone, urges you: “The police told me to move all the money into this holding account for an investigation and to tell no one.” People in the queue complain and ask you to just get it done."},options:{safe:{vi:"Tạm dừng lệnh chuyển theo quy trình phòng chống lừa đảo, báo kiểm soát viên, giải thích dấu hiệu giả danh cơ quan chức năng và hỗ trợ khách liên hệ người thân hoặc công an qua số chính thức.",en:"Pause the transfer under the anti-fraud procedure, alert the supervisor, explain the impersonation red flags and help the customer contact family or the police on an official number."},shortcut:{vi:"Làm nhanh theo yêu cầu vì tiền là của khách và hàng chờ đang dài.",en:"Process it quickly because it is the customer's money and the queue is long."},wait:{vi:"Trả lại sổ, bảo khách tự quyết định và không báo cho ai.",en:"Hand back the book, tell the customer to decide alone and alert no one."}},questions:{vi:["Hãy giải thích cho khách vì sao tiền lãi chỉ còn 240000 đồng thay vì 6720000 đồng, dựa trên biểu lãi suất và cách tính.","Những dấu hiệu nào cho thấy khách đang bị lừa đảo và bạn phối hợp với ai để bảo vệ khách mà vẫn tôn trọng quyền của khách?"],en:["Explain to the customer why the interest is only 240000 VND instead of 6720000 VND, using the rate sheet and the formula.","Which signs show the customer is being scammed, and whom do you involve to protect them while respecting their rights?"]},hints:{vi:["Đối chiếu tình trạng rút trước hạn với từng dòng của biểu lãi suất.","Áp lãi suất đúng vào công thức số ngày thực tế/365 ở SOP mục 3.2.","Đọc SOP mục 4.2: giao dịch có dấu hiệu lừa đảo phải tạm dừng và báo kiểm soát viên ngay."],en:["Match the early withdrawal status with each line of the rate sheet.","Apply the correct rate in the actual days/365 formula in SOP 3.2.","Re-read SOP 4.2: a transaction with fraud signs must be paused and reported to the supervisor at once."]}},learning:{summary:{vi:"Giao dịch viên ngân hàng là gương mặt đầu tiên của chi nhánh: mở tài khoản, nhận gửi và chi trả tiền gửi, chuyển tiền, thu đổi ngoại tệ, kiểm đếm tiền mặt và hướng dẫn khách dùng dịch vụ số. Nghề đòi hỏi chính xác tuyệt đối với tiền và chứng từ, giải thích dễ hiểu cho mọi khách hàng, nhận diện giấy tờ giả, thủ đoạn lừa đảo và tuân thủ nguyên tắc kiểm soát kép.",en:"A bank teller is the first face of the branch: opening accounts, taking and paying out deposits, making transfers, exchanging currency, counting cash and guiding customers to digital services. The role demands absolute accuracy with cash and documents, clear explanations for every customer, detection of forged papers and scams, and strict maker-checker discipline."},responsibilities:{vi:["Nhận biết khách hàng, kiểm tra giấy tờ tùy thân và thẩm quyền giao dịch.","Thực hiện gửi, rút, tất toán tiền gửi và tính lãi đúng biểu lãi suất.","Xử lý chuyển tiền, thu đổi ngoại tệ, nộp rút tiền mặt theo hạn mức được giao.","Tư vấn sản phẩm cơ bản, hướng dẫn khách dùng ngân hàng số an toàn.","Kiểm quỹ cuối ngày, đối chiếu chứng từ và bàn giao cho kiểm soát viên."],en:["Identify customers and check ID and signing authority.","Process deposits, withdrawals and closures and calculate interest per the rate sheet.","Handle transfers, currency exchange and cash within assigned limits.","Advise on basic products and guide customers to use digital banking safely.","Balance the cash drawer, reconcile vouchers and hand over to the supervisor."]},competencies:[{name:{vi:"Chính xác nghiệp vụ",en:"Operational accuracy"},desc:{vi:"Tính lãi, phí, tỷ giá và kiểm đếm tiền không sai sót, lập chứng từ đúng mẫu.",en:"Calculate interest, fees and rates and count cash without error, with correct vouchers."}},{name:{vi:"Giao tiếp khách hàng",en:"Customer communication"},desc:{vi:"Giải thích quy định, tiền lãi, phí bằng ngôn ngữ dễ hiểu, kiên nhẫn với người cao tuổi.",en:"Explain rules, interest and fees in plain words, patiently with elderly customers."}},{name:{vi:"Nhận diện gian lận",en:"Fraud detection"},desc:{vi:"Phát hiện giấy tờ giả, ủy quyền không hợp lệ, khách bị dẫn dắt chuyển tiền.",en:"Spot forged IDs, invalid mandates and customers coached into transfers."}},{name:{vi:"Tuân thủ quy trình",en:"Procedure compliance"},desc:{vi:"Thực hiện đúng kiểm soát kép, hạn mức giao dịch và quy định nhận biết khách hàng.",en:"Follow maker-checker controls, transaction limits and customer identification rules."}},{name:{vi:"Bình tĩnh dưới áp lực",en:"Composure under pressure"},desc:{vi:"Giữ đúng quy trình khi hàng chờ dài, khách nóng giận hoặc bị thúc ép.",en:"Stick to procedure when queues are long or customers are upset or pressured."}}],knowledge:{vi:["Thông tư 48/2018/TT-NHNN về tiền gửi tiết kiệm (sửa đổi bởi Thông tư 04/2022/TT-NHNN) và quy định rút trước hạn.","Thông tư 14/2017/TT-NHNN về phương pháp tính lãi trong hoạt động nhận tiền gửi, cấp tín dụng.","Quy định hiện hành về nhận biết khách hàng, xác thực giấy tờ tùy thân và sinh trắc học.","Nhận biết tiền thật, tiền giả; quy trình kiểm đếm, đóng gói và bàn giao quỹ cuối ngày.","Thủ đoạn lừa đảo phổ biến: giả danh cơ quan chức năng, chiếm đoạt OTP, chuyển tiền bất thường."],en:["Circular 48/2018/TT-NHNN on savings deposits (amended by Circular 04/2022/TT-NHNN) and early withdrawal rules.","Circular 14/2017/TT-NHNN on interest calculation for deposits and credit.","Current rules on customer identification, ID verification and biometrics.","Detecting counterfeit notes; counting, bundling and end-of-day cash handover.","Common scams: impersonating authorities, OTP theft and unusual transfer requests."]},tools:["Core Banking teller module","Queue management system","Cash counter & counterfeit detector","Chip ID & biometric reader","Rate sheet & fee schedule","Fraud alert checklist"],tools_en:["Core Banking teller module","Queue management system","Cash counter & counterfeit detector","Chip ID & biometric reader","Rate sheet & fee schedule","Fraud alert checklist"],kpis:{vi:["Số giao dịch sai sót phải điều chỉnh (mục tiêu bằng 0).","Thời gian phục vụ trung bình mỗi khách.","Điểm hài lòng của khách hàng tại quầy.","Số vụ lừa đảo được phát hiện và ngăn chặn kịp thời."],en:["Transactions needing correction (target zero).","Average service time per customer.","Counter customer satisfaction score.","Scams detected and stopped in time."]},day:[{time:"07:45",vi:"Nhận quỹ đầu ngày, kiểm đếm và ký biên bản với thủ quỹ.",en:"Receive the opening cash float, count it and sign off with the vault teller."},{time:"08:00",vi:"Mở quầy, phục vụ gửi rút tiết kiệm, chuyển tiền và mở tài khoản.",en:"Open the counter for savings, transfers and new accounts."},{time:"11:30",vi:"Trình kiểm soát viên duyệt các giao dịch vượt hạn mức.",en:"Submit over-limit transactions to the supervisor for approval."},{time:"14:00",vi:"Hướng dẫn khách cài đặt ngân hàng số và cảnh báo thủ đoạn lừa đảo.",en:"Help customers set up digital banking and warn them about scams."},{time:"16:30",vi:"Kiểm quỹ cuối ngày, đối chiếu chứng từ và nộp quỹ.",en:"Balance the drawer, reconcile vouchers and return the cash."}],mistakes:{vi:["Áp lãi suất kỳ hạn cho khoản rút trước hạn, chi thừa tiền lãi.","Chi tiền cho người không có ủy quyền hợp lệ dù mang đủ giấy tờ của chủ tài khoản.","Làm nhanh giao dịch chuyển tiền bất thường của người cao tuổi mà không hỏi han, cảnh báo."],en:["Paying the term rate on an early withdrawal, overpaying interest.","Paying someone without a valid mandate even if they hold the owner's papers.","Rushing an unusual transfer for an elderly customer without asking or warning."]},career:[{vi:"Giao dịch viên",en:"Bank teller"},{vi:"Giao dịch viên cao cấp / Chuyên viên dịch vụ khách hàng",en:"Senior teller / Customer service officer"},{vi:"Kiểm soát viên giao dịch",en:"Teller supervisor"},{vi:"Trưởng phòng Giao dịch / Phó giám đốc chi nhánh",en:"Branch operations manager / Deputy branch director"}],glossary:[{term:"Demand deposit rate",vi:"Lãi suất không kỳ hạn, thường áp dụng khi khách rút tiền gửi có kỳ hạn trước hạn.",en:"The non-term rate, usually paid when a term deposit is withdrawn early."},{term:"Early withdrawal",vi:"Rút một phần hoặc toàn bộ tiền gửi có kỳ hạn trước ngày đến hạn.",en:"Withdrawing part or all of a term deposit before its maturity date."},{term:"Maker-checker",vi:"Nguyên tắc kiểm soát kép: một người lập giao dịch, người khác kiểm tra và phê duyệt.",en:"Dual control: one person enters a transaction and another checks and approves it."},{term:"Biometric authentication",vi:"Xác thực khách hàng bằng đặc điểm sinh trắc như khuôn mặt, vân tay so với dữ liệu căn cước.",en:"Verifying customers by face or fingerprint against ID records."},{term:"Impersonation scam",vi:"Lừa đảo giả danh công an, ngân hàng, cơ quan thuế để ép nạn nhân chuyển tiền.",en:"A scam where fraudsters pose as police, banks or tax officers to force transfers."}],quiz:[{q:{vi:"Gốc 100000000 đồng, rút trước hạn sau 73 ngày, lãi suất không kỳ hạn 0,5%/năm, cơ sở 365 ngày. Tiền lãi là bao nhiêu?",en:"Principal 100000000 VND, early withdrawal after 73 days, demand rate 0.5% per year, 365-day basis. What is the interest?"},options:{vi:["500000 đồng","100000 đồng","73000 đồng","1000000 đồng"],en:["500000 VND","100000 VND","73000 VND","1000000 VND"]},answer:1,explain:{vi:"Tiền lãi = 100000000 x 0,5% x 73 / 365 = 100000 đồng.",en:"Interest = 100000000 x 0.5% x 73 / 365 = 100000 VND."}},{q:{vi:"Một người mang căn cước và sổ tiết kiệm của mẹ đến rút tiền, không có giấy ủy quyền. Bạn làm gì?",en:"Someone brings their mother's ID and savings book to withdraw, with no power of attorney. What do you do?"},options:{vi:["Chi tiền vì có đủ giấy tờ gốc","Gọi điện cho người mẹ rồi chi","Từ chối chi, hướng dẫn thủ tục ủy quyền hợp lệ theo quy định","Chi một nửa số tiền"],en:["Pay because the originals are present","Call the mother and then pay","Decline and explain the valid mandate procedure","Pay half the amount"]},answer:2,explain:{vi:"Chỉ chủ tài khoản hoặc người được ủy quyền hợp pháp mới được rút tiền; giấy tờ gốc không thay thế ủy quyền.",en:"Only the owner or a lawful attorney may withdraw; holding originals is not a mandate."}},{q:{vi:"Khách cao tuổi đòi chuyển toàn bộ tiền vào “tài khoản tạm giữ của công an”. Phản ứng đúng là gì?",en:"An elderly customer insists on moving all savings to a “police holding account”. What is the right response?"},options:{vi:["Tạm dừng, báo kiểm soát viên, giải thích dấu hiệu lừa đảo và hỗ trợ khách xác minh qua kênh chính thức","Chuyển ngay vì là tiền của khách","Từ chối thẳng và mời khách ra về","Xin số tài khoản rồi tự chuyển giúp"],en:["Pause, alert the supervisor, explain the scam signs and help verify via official channels","Transfer at once because it is the customer's money","Refuse bluntly and send the customer away","Take the account number and transfer it yourself"]},answer:0,explain:{vi:"Cơ quan chức năng không yêu cầu chuyển tiền vào tài khoản tạm giữ qua điện thoại; giao dịch viên phải tạm dừng và báo cáo.",en:"Authorities never ask for transfers to holding accounts by phone; the teller must pause and escalate."}},{q:{vi:"Cuối ngày quỹ tiền mặt thừa 500000 đồng so với sổ. Xử lý đúng là gì?",en:"At day end the cash drawer is 500000 VND over the books. What is correct?"},options:{vi:["Giữ lại để bù lần thiếu sau","Chia cho cả tổ","Bỏ vào quỹ chung không ghi chép","Lập biên bản, báo kiểm soát viên và hạch toán chờ xử lý theo quy trình"],en:["Keep it to cover a future shortage","Share it with the team","Drop it in a common fund unrecorded","Record it, report to the supervisor and post it to suspense per procedure"]},answer:3,explain:{vi:"Mọi chênh lệch quỹ phải được lập biên bản, báo cáo và hạch toán minh bạch để tìm nguyên nhân.",en:"Every cash difference must be recorded, reported and posted transparently to find the cause."}}]}}})})(window.KKR);
